func LinkTargetLTE(v []byte) predicate.File {
	return predicate.File(sql.FieldLTE(FieldLinkTarget, v))
}

// LinkTargetIsNil applies the IsNil predicate on the "link_target" field.
func LinkTargetIsNil() predicate.File {
	return predicate.File(sql.FieldIsNull(FieldLinkTarget))
}

// LinkTargetNotNil applies the NotNil predicate on the "link_target" field.
func LinkTargetNotNil() predicate.File {
	return predicate.File(sql.FieldNotNull(FieldLinkTarget))
}

// LostEQ applies the EQ predicate on the "lost" field.
func LostEQ(v bool) predicate.File {
	return predicate.File(sql.FieldEQ(FieldLost, v))
}

// LostNEQ applies the NEQ predicate on the "lost" field.
func LostNEQ(v bool) predicate.File {
	return predicate.File(sql.FieldNEQ(FieldLost, v))
}

// HasSet applies the HasEdge predicate on the "set" edge.
func HasSet() predicate.File {
	return predicate.File(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SetTable, SetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSetWith applies the HasEdge predicate on the "set" edge with a given conditions (other predicates).
func HasSetWith(preds ...predicate.Set) predicate.File {
	return predicate.File(func(s *sql.Selector) {
		step := newSetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.File) predicate.File {
	return predicate.File(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.File) predicate.File {
	return predicate.File(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.File) predicate.File {
	return predicate.File(sql.NotPredicates(p))
}
